_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


def _round_output(value: float) -> float:
    value = round(value, 12)
    if value == 0.0:
        # Normalize negative zero.
        return 0.0
    return value


def _is_finite(value: Any) -> bool:
    try:
        return math.isfinite(value)
    except OverflowError:
        # Huge ints cannot be represented as finite floats.
        return False


def _as_finite_float(value: Any) -> float:
    """Convert a number to a finite float or raise ``ValueError``.

    ``OverflowError`` from a finite int too large to represent is turned
    into the same ``ValueError`` used for non-finite derived statistics.
    """
    try:
        as_float = float(value)
    except OverflowError:
        raise ValueError("derived statistics must be finite") from None
    if not _is_finite(as_float):
        raise ValueError("derived statistics must be finite")
    return as_float


def _scaled_mean_std(values: Any, n: int) -> tuple[float, float]:
    """Mean and population standard deviation, computed without overflow.

    The inputs are divided by the largest finite absolute value before
    the ``fsum`` accumulation and the root mean square is taken as
    ``M · hypot(deviations / M)``, so no intermediate term is squared
    unscaled.  ``ValueError`` is raised when a value cannot convert to a
    finite float or when either derived statistic is non-finite.
    """
    scaled_values: list[float] = []
    largest = 0.0
    for value in values:
        as_float = _as_finite_float(value)
        scaled_values.append(as_float)
        magnitude = abs(as_float)
        if magnitude > largest:
            largest = magnitude

    if largest == 0.0:
        return 0.0, 0.0

    mean = (largest / n) * math.fsum(
        value / largest for value in scaled_values
    )
    if not _is_finite(mean):
        raise ValueError("derived statistics must be finite")
    std = largest * (
        math.hypot(*((value - mean) / largest for value in scaled_values))
        / math.sqrt(n)
    )
    if not _is_finite(std):
        raise ValueError("derived statistics must be finite")
    return mean, std


def _parse_date(value: Any, where: str) -> datetime.date:
    if not isinstance(value, str):
        raise TypeError(f"{where} must be a str")
    if _DATE_RE.fullmatch(value) is None:
        raise ValueError(f"{where} must be a YYYY-MM-DD date")
    year, month, day = (int(part) for part in value.split("-"))
    try:
        return datetime.date(year, month, day)

def _validate_string_list(values: Any, name: str, *, minimum: int = 1) -> list[str]:
    if not isinstance(values, list):
        raise TypeError(f"{name} must be a list")
    if len(values) < minimum:
        raise ValueError(f"{name} must contain at least {minimum} items")
    seen: set[str] = set()
    for index, value in enumerate(values):
        if not isinstance(value, str):
            raise TypeError(f"{name}[{index}] must be a str")
        if value == "":
            raise ValueError(f"{name}[{index}] must be non-empty")
        if value in seen:
            raise ValueError(f"duplicate {name} entry: {value!r}")
        seen.add(value)
    return values


def _validate_rank_attribute_batch(
    attribution: Any, *, where: str = "attribution"
) -> tuple[str, list[str], list[str], list[str], dict]:
    if not isinstance(attribution, dict):
        raise TypeError(f"{where} must be a dict")
    if tuple(attribution.keys()) != _RANK_ATTRIBUTE_BATCH_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, reference, configs, "
            "elements, drivers, data in order"
        )

    schema = attribution["schema"]
    if not isinstance(schema, str):
        raise TypeError(f"{where}.schema must be a str")
    if schema != _RANK_ATTRIBUTE_BATCH_SCHEMA:
        raise ValueError(f"{where}.schema must be {_RANK_ATTRIBUTE_BATCH_SCHEMA!r}")

    reference = attribution["reference"]
    if not isinstance(reference, str):
        raise TypeError(f"{where}.reference must be a str")
    if reference == "":
        raise ValueError(f"{where}.reference must be non-empty")

_PANEL_STABILITY_MINIMUM_PROFILE_SCHEMA = "climate-grid/ps-minimum-profile-v1"


def _validate_profile_minimums(minimums: Any) -> list:
    if not isinstance(minimums, list):
        raise TypeError("minimums must be a list")
    if len(minimums) == 0:
        raise ValueError("minimums must be non-empty")

    previous = None
    for index, minimum in enumerate(minimums):
        if not isinstance(minimum, int) or isinstance(minimum, bool):
            raise TypeError(f"minimums[{index}] must be a non-bool int")
        if minimum <= 0:
            raise ValueError(f"minimums[{index}] must be positive")
        if previous is not None and not minimum > previous:
            raise ValueError("minimums must be strictly increasing")
        previous = minimum

    return minimums

