unique; ``result`` is a complete :func:`profile_set` result (schema
``climate-grid/psd-set-v1``), validated against that contract.
Every result must share equal ``factor``, ``minimums`` and
``thresholds`` (in the same order).  The ``scales`` and ``panels``
axes list each label at its first appearance, and each scale must
label at least two items.  A wrong container or entry type raises
``TypeError``; any other contract violation, or a non-finite or
overflowing derived value, raises ``ValueError``.

For each scale and minimum the ``n`` results with that scale are
aggregated threshold by threshold.  For each threshold, ``d`` is
the mean ``fsum(C.d) / n`` of the results' ``d`` values, ``u`` is
``hypot(*C.u) / n`` and ``band`` is the two-item list
``[d - factor * u, d + factor * u]``; the results' peaks use the
same formulas, giving ``pd``, ``pu`` and ``pband``.

The returned mapping uses the key order ``schema, factor, scales,
panels, minimums, thresholds, data``; ``schema`` is
``climate-grid/psd-panel-v1``, ``factor`` and the axes are taken
from the first result (fresh copies) and ``panels`` lists the first-
appearance panel order.  ``data`` follows scale order then minimum
order; each row uses the key order ``scale, minimum, count, d, u,
band, pd, pu, pband`` where ``count`` is ``n``, ``d``, ``u`` and
``band`` follow threshold order and each ``band`` entry and
``pband`` are two-item lists.  Every derived float is
``round(x, 12)`` with negative zero normalized to ``0.0``; every
output list is newly constructed and the inputs are not modified.
"""
if not isinstance(items, list):
    raise TypeError("items must be a list")
if len(items) < 2:
    raise ValueError("items must contain at least two items")

scales: list[str] = []
panels: list[str] = []
seen_pairs: set[tuple[str, str]] = set()
factor: Any = None
minimums: list = []
thresholds: list = []
# Per scale, in item order: (panel, validated rows).
rows_by_scale: dict[str, list[tuple[str, list[dict]]]] = {}
for index, item in enumerate(items):
    where = f"items[{index}]"
    if not isinstance(item, dict):
        raise TypeError(f"{where} must be a dict")
    if tuple(item.keys()) != _PROFILE_PANEL_SET_ITEM_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys scale, panel, "
            "result in order"
        )

    scale = item["scale"]
    if not isinstance(scale, str):
        raise TypeError(f"{where}.scale must be a str")
    if scale == "":
        raise ValueError(f"{where}.scale must be non-empty")
    panel = item["panel"]
    if not isinstance(panel, str):
        raise TypeError(f"{where}.panel must be a str")
    if panel == "":
        raise ValueError(f"{where}.panel must be non-empty")
    pair = (scale, panel)
    if pair in seen_pairs:
        raise ValueError(
            f"duplicate items scale/panel pair: {scale!r}, {panel!r}"
        )
    seen_pairs.add(pair)

    item_factor, item_minimums, item_thresholds, item_rows = (
        _validate_profile_set_result(item["result"], where=f"{where}.result")
    )

    if not rows_by_scale:
        factor = item_factor
        minimums = item_minimums
        thresholds = item_thresholds
    else:
        if item_factor != factor:
            raise ValueError(
                "all items must have equal factor, taken from the "
                "first item"
            )
        if item_minimums != minimums:
            raise ValueError(
                "all items must have equal minimums in the same order, "
                "taken from the first item"
            )
        if item_thresholds != thresholds:
            raise ValueError(
                "all items must have equal thresholds in the same "
                "order, taken from the first item"
            )

    if scale not in rows_by_scale:
        scales.append(scale)
        rows_by_scale[scale] = []
    if panel not in panels:
        panels.append(panel)
    rows_by_scale[scale].append((panel, item_rows))

for scale in scales:
    if len(rows_by_scale[scale]) < 2:
        raise ValueError(
            f"each scale must label at least two items: {scale!r}"
        )

data: list[dict] = []
for scale in scales:
    scale_entries = rows_by_scale[scale]
    n = len(scale_entries)
    for minimum_index, minimum in enumerate(minimums):
        scale_rows = [
            entry_rows[minimum_index] for _panel, entry_rows in scale_entries
        ]
        d_values: list[float] = []
        u_values: list[float] = []
        band_values: list[list[float]] = []
        for threshold_index in range(len(thresholds)):
            try:
                d = math.fsum(
                    _as_finite_float(row["d"][threshold_index])
                    for row in scale_rows
                ) / n
            except OverflowError:
                # An overflowing fsum sum is a non-finite derived value.
                raise ValueError(
                    "derived statistics must be finite"
                ) from None
            u = math.hypot(
                *(
                    _as_finite_float(row["u"][threshold_index])
                    for row in scale_rows
                )
            ) / n
            try:
                lower = d - factor * u
                upper = d + factor * u
            except OverflowError:
                # Huge int factors overflow float arithmetic.
                raise ValueError(
                    "derived statistics must be finite"
                ) from None
            if not all(_is_finite(value) for value in (d, u, lower, upper)):
                raise ValueError("derived statistics must be finite")
            d_values.append(_round_output(d))
            u_values.append(_round_output(u))
            band_values.append(
                [_round_output(lower), _round_output(upper)]
            )

        try:
            pd = math.fsum(
                _as_finite_float(row["pd"]) for row in scale_rows
            ) / n
        except OverflowError:
            # An overflowing fsum sum is a non-finite derived value.
            raise ValueError("derived statistics must be finite") from None
        pu = math.hypot(
            *(_as_finite_float(row["pu"]) for row in scale_rows)
        ) / n
        try:
            peak_lower = pd - factor * pu
            peak_upper = pd + factor * pu
        except OverflowError:
            # Huge int factors overflow float arithmetic.
            raise ValueError("derived statistics must be finite") from None
        if not all(
            _is_finite(value) for value in (pd, pu, peak_lower, peak_upper)
        ):
            raise ValueError("derived statistics must be finite")

        data.append(
            {
                "scale": scale,
                "minimum": minimum,
                "count": n,
                "d": d_values,
                "u": u_values,
                "band": band_values,
                "pd": _round_output(pd),
                "pu": _round_output(pu),
                "pband": [
                    _round_output(peak_lower),
                    _round_output(peak_upper),
                ],
            }
        )

return {
    "schema": _PROFILE_PANEL_SET_SCHEMA,
    "factor": _round_output(factor),
    "scales": list(scales),
    "panels": list(panels),
    "minimums": list(minimums),
    "thresholds": list(thresholds),
    "data": data,
}
